junk={'атад','и','.пдоП','№','.вни','.мазВ','.лбуд','.внИ','пдоп'}
t=open('_nk/text/тс.pdf.txt').read()
pages=re.split(r'=== PAGE (\d+) ===',t)
for i in range(1,len(pages),2):
    n=int(pages[i]); body='\n'.join(l for l in pages[i+1].split('\n') if l.strip() not in junk)
    if n<=4: print('#####',n); print(body[:7000])
    else:
        m=re.findall(r'(№?25Д\S*[^\n]*|Стадия[^\n]*\n[^\n]*\n[^\n]*|РП ?\d[^\n]*)',body)
        print('#####',n,len(body), m[:4])
E

